import{_ as t,a,o as n,a6 as i}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Create Sitemap","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"create","title":"Create Sitemap","description":"Create a sitemap definition. The XML is not built on save — call generate explicitly.","query":"curl -X POST \\"https://your-domain.com/api/admin/marketing/sitemaps\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d '{\\n    \\"file_name\\": \\"sitemap.xml\\",\\n    \\"path\\": \\"/\\",\\n    \\"channels\\": [1]\\n  }'\\n","variables":"{}\\n","response":"{\\n  \\"id\\": 1,\\n  \\"fileName\\": \\"sitemap.xml\\",\\n  \\"path\\": \\"/\\",\\n  \\"channels\\": [1],\\n  \\"urls\\": [\\n    \\"https://example.com/storage/sitemaps/default/sitemap-1-1.xml\\"\\n  ],\\n  \\"generatedAt\\": null,\\n  \\"generatedFiles\\": [],\\n  \\"indexFile\\": null,\\n  \\"generatedSitemaps\\": [],\\n  \\"createdAt\\": \\"2026-06-20T10:00:00+05:30\\",\\n  \\"updatedAt\\": \\"2026-06-20T10:00:00+05:30\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/marketing/search-seo/sitemaps-create.md","filePath":"api/rest-api/admin/marketing/search-seo/sitemaps-create.md","lastUpdated":1789385991000}`),s={name:"api/rest-api/admin/marketing/search-seo/sitemaps-create.md"};function o(r,e,d,l,h,p){return n(),a("div",null,e[0]||(e[0]=[i('<h1 id="create-sitemap" tabindex="-1">Create Sitemap <a class="header-anchor" href="#create-sitemap" aria-label="Permalink to &quot;Create Sitemap&quot;">​</a></h1><p>Creates a sitemap definition — the <strong>Create Sitemap</strong> action on the admin <strong>Marketing → Search &amp; SEO → Sitemaps</strong> screen.</p><p>New here? Read the <a href="/api/rest-api/admin/marketing/search-seo/sitemaps/">Sitemaps overview</a> for what a sitemap does and how its fields behave.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/marketing/sitemaps</code></td><td>POST</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.search_seo.sitemaps.create</code> permission.</li><li>Returns the full sitemap payload.</li></ul><h3 id="one-sitemap-one-set-of-files-per-channel" tabindex="-1">One sitemap, one set of files per channel <a class="header-anchor" href="#one-sitemap-one-set-of-files-per-channel" aria-label="Permalink to &quot;One sitemap, one set of files per channel&quot;">​</a></h3><p>A sitemap covers the channels you list, and generation writes an index plus its child files for each of them — a channel&#39;s own hostname, its root category and the products and pages assigned to it. <code>urls</code> returns the public index URL per channel, which is the link to submit to a search engine.</p><h3 id="the-xml-is-not-built-on-save" tabindex="-1">The XML is not built on save <a class="header-anchor" href="#the-xml-is-not-built-on-save" aria-label="Permalink to &quot;The XML is not built on save&quot;">​</a></h3><p>Creating the row only registers the definition — <code>generatedAt</code> and <code>generatedFiles</code> stay empty. Call <a href="/api/rest-api/admin/marketing/search-seo/sitemaps-generate.html">generate</a> (<code>POST /api/admin/marketing/sitemaps/{id}/generate</code>) to build the XML files.</p><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>file_name</code></td><td>string</td><td>yes</td><td>Index file name — letters, digits, <code>-</code>, <code>_</code>, <code>.</code>; must end with <code>.xml</code></td></tr><tr><td><code>path</code></td><td>string</td><td>yes</td><td>Where the index file is written — must start and end with <code>/</code>, no <code>//</code></td></tr><tr><td><code>channels</code></td><td>integer[]</td><td>yes</td><td>Channel ids the sitemap covers. At least one — generation walks the channels, so a sitemap covering none produces no files</td></tr></tbody></table>',13)]))}const u=t(s,[["render",o]]);export{m as __pageData,u as default};
